{
  "items": [
    {
      "full_name": "MeasureTheory.Integrable.of_bound",
      "formal_statement": "Formal Name: MeasureTheory.Integrable.of_bound | Kind: theorem | Type: ∀ {α : Type u_1} {E : Type u_5} {mα : MeasurableSpace α} [inst : NormedAddCommGroup E] {μ : MeasureTheory.Measure α}\n  [MeasureTheory.IsFiniteMeasure μ] {f : α → E},\n  MeasureTheory.AEStronglyMeasurable f μ → ∀ (C : ℝ), (∀ᵐ (x : α) ∂μ, ‖f x‖ ≤ C) → MeasureTheory.Integrable f μ | Path: Mathlib.MeasureTheory.Integral.IntegrableOn",
      "informal_statement": "Let $(\\alpha,\\mathcal{A})$ be a measurable space, let $E$ be a normed additive commutative group, let $\\mu$ be a finite measure on $\\alpha$, and let $f:\\alpha\\to E$ be a function. If $f$ is almost everywhere strongly measurable with respect to $\\mu$ and there exists a real number $C$ such that $\\|f(x)\\|\\le C$ for $\\mu$‑almost every $x\\in\\alpha$, then $f$ is integrable with respect to $\\mu$ (i.e. $\\int_{\\alpha}\\|f(x)\\|\\,d\\mu<\\infty$)."
    },
    {
      "full_name": "MeasureTheory.IntegrableOn.of_bound",
      "formal_statement": "Formal Name: MeasureTheory.IntegrableOn.of_bound | Kind: theorem | Type: ∀ {α : Type u_1} {E : Type u_5} {mα : MeasurableSpace α} [inst : NormedAddCommGroup E] {s : Set α}\n  {μ : MeasureTheory.Measure α},\n  μ s < ⊤ →\n    ∀ {f : α → E},\n      MeasureTheory.AEStronglyMeasurable f (μ.restrict s) →\n        ∀ (C : ℝ), (∀ᵐ (x : α) ∂μ.restrict s, ‖f x‖ ≤ C) → MeasureTheory.IntegrableOn f s μ | Path: Mathlib.MeasureTheory.Integral.IntegrableOn",
      "informal_statement": "Let $(\\alpha,\\mathcal{A})$ be a measurable space and let $\\mu$ be a measure on $\\alpha$.  Let $s\\subseteq\\alpha$ be a measurable set with finite measure, $\\mu(s)<\\infty$.  Let $E$ be a normed additive commutative group and $f:\\alpha\\to E$ a function.  Suppose that $f$ is \\emph{almost everywhere strongly measurable} with respect to the restricted measure $\\mu|_{s}$ (i.e. $f$ is strongly measurable on $s$ up to a $\\mu$‑null set) and that there exists a real constant $C$ such that\\[\\|f(x)\\|\\le C\\quad\\text{for }\\mu|_{s}\\text{-almost every }x\\in s.\\]  Then $f$ is integrable on $s$ with respect to $\\mu$, that is, $f\\in L^{1}(\\mu|_{s})$ (equivalently, $\\operatorname{IntegrableOn}\\,f\\,s\\,\\mu$)."
    },
    {
      "full_name": "MeasureTheory.Measure.integrableOn_of_bounded",
      "formal_statement": "Formal Name: MeasureTheory.Measure.integrableOn_of_bounded | Kind: theorem | Type: ∀ {α : Type u_1} {E : Type u_5} {mα : MeasurableSpace α} [inst : NormedAddCommGroup E] {s : Set α}\n  {μ : MeasureTheory.Measure α} {f : α → E},\n  μ s ≠ ⊤ →\n    MeasureTheory.AEStronglyMeasurable f μ →\n      ∀ {M : ℝ}, (∀ᵐ (a : α) ∂μ.restrict s, ‖f a‖ ≤ M) → MeasureTheory.IntegrableOn f s μ | Path: Mathlib.MeasureTheory.Integral.IntegrableOn",
      "informal_statement": "Let $E$ be a normed additive commutative group, $f \\colon \\alpha \\to E$ a function, and $\\mu$ a measure on $\\alpha$. For a measurable set $s \\subseteq \\alpha$ with $\\mu(s) < \\infty$, if $f$ is almost everywhere strongly measurable with respect to $\\mu$ and there exists a real number $M$ such that $\\|f(a)\\| \\leq M$ holds for almost every $a \\in s$ with respect to the restricted measure $\\mu|_s$, then $f$ is integrable on $s$ with respect to $\\mu$."
    },
    {
      "full_name": "MeasureTheory.Integrable.bdd_mul",
      "formal_statement": "Formal Name: MeasureTheory.Integrable.bdd_mul | Kind: theorem | Type: ∀ {α : Type u_1} {m : MeasurableSpace α} {μ : MeasureTheory.Measure α} {𝕜 : Type u_8} [inst : NormedRing 𝕜]\n  {f g : α → 𝕜} {c : ℝ},\n  MeasureTheory.Integrable g μ →\n    MeasureTheory.AEStronglyMeasurable f μ →\n      (∀ᵐ (x : α) ∂μ, ‖f x‖ ≤ c) → MeasureTheory.Integrable (fun x => f x * g x) μ | Path: Mathlib.MeasureTheory.Function.L1Space.Integrable",
      "informal_statement": "Let $F$ be a normed division ring, and let $f, g \\colon \\alpha \\to F$ be functions. If $g$ is integrable with respect to a measure $\\mu$, $f$ is almost everywhere strongly measurable with respect to $\\mu$, and $f$ is uniformly bounded (i.e., there exists a constant $C$ such that $\\|f(x)\\| \\leq C$ for all $x \\in \\alpha$), then the function $x \\mapsto f(x) \\cdot g(x)$ is integrable with respect to $\\mu$."
    },
    {
      "full_name": "MeasureTheory.Integrable.mul_bdd",
      "formal_statement": "Formal Name: MeasureTheory.Integrable.mul_bdd | Kind: theorem | Type: ∀ {α : Type u_1} {m : MeasurableSpace α} {μ : MeasureTheory.Measure α} {𝕜 : Type u_8} [inst : NormedRing 𝕜]\n  {f g : α → 𝕜} {c : ℝ},\n  MeasureTheory.Integrable f μ →\n    MeasureTheory.AEStronglyMeasurable g μ →\n      (∀ᵐ (x : α) ∂μ, ‖g x‖ ≤ c) → MeasureTheory.Integrable (fun x => f x * g x) μ | Path: Mathlib.MeasureTheory.Function.L1Space.Integrable",
      "informal_statement": "Let $(\\alpha,\\mathcal{A},\\mu)$ be a measurable space with measure $\\mu$, and let $\\mathbb{k}$ be a normed ring.  Suppose $f\\colon\\alpha\\to\\mathbb{k}$ is $\\mu$‑integrable and $g\\colon\\alpha\\to\\mathbb{k}$ is almost everywhere strongly measurable.  If there exists a constant $c\\in\\mathbb{R}$ such that $\\|g(x)\\|\\le c$ for $\\mu$‑almost every $x\\in\\alpha$ (i.e. $\\forall^{\\text{a.e.}}x\\,\\|g(x)\\|\\le c$), then the pointwise product $x\\mapsto f(x)\\cdot g(x)$ is $\\mu$‑integrable."
    },
    {
      "full_name": "MeasureTheory.Integrable.smul_bdd",
      "formal_statement": "Formal Name: MeasureTheory.Integrable.smul_bdd | Kind: theorem | Type: ∀ {α : Type u_1} {β : Type u_2} {m : MeasurableSpace α} {μ : MeasureTheory.Measure α} [inst : NormedAddCommGroup β]\n  {𝕜 : Type u_8} [inst_1 : NormedRing 𝕜] [inst_2 : Module 𝕜 β] [IsBoundedSMul 𝕜 β] {f : α → β} {φ : α → 𝕜},\n  MeasureTheory.Integrable φ μ →\n    ∀ (C : ℝ), MeasureTheory.AEStronglyMeasurable f μ → (∀ᵐ (a : α) ∂μ, ‖f a‖ ≤ C) → MeasureTheory.Integrable (φ • f) μ | Path: Mathlib.MeasureTheory.Function.L1Space.Integrable",
      "informal_statement": "Let $\\alpha$ be a measurable space with measure $\\mu$, let $\\mathbb{k}$ be a normed ring, and let $\\beta$ be a normed additive commutative group on which scalar multiplication by $\\mathbb{k}$ is bounded (i.e. $\\mathbb{k}\\times\\beta\\to\\beta$ satisfies the boundedness property).  Suppose $\\varphi\\colon\\alpha\\to\\mathbb{k}$ is integrable with respect to $\\mu$, and $f\\colon\\alpha\\to\\beta$ is almost everywhere strongly measurable and essentially bounded by a constant $C\\in\\mathbb{R}$, meaning that $\\|f(a)\\|\\le C$ for $\\mu$‑almost all $a\\in\\alpha$.  Then the pointwise scalar multiple $\\varphi\\,\\bullet\\,f\\colon\\alpha\\to\\beta$, defined by $(\\varphi\\bullet f)(a)=\\varphi(a)\\,\\bullet\\,f(a)$, is integrable with respect to $\\mu$."
    },
    {
      "full_name": "MeasureTheory.Integrable.aestronglyMeasurable",
      "formal_statement": "Formal Name: MeasureTheory.Integrable.aestronglyMeasurable | Kind: theorem | Type: ∀ {α : Type u_1} {ε : Type u_5} {m : MeasurableSpace α} {μ : MeasureTheory.Measure α} [inst : TopologicalSpace ε]\n  [inst_1 : ContinuousENorm ε] {f : α → ε}, MeasureTheory.Integrable f μ → MeasureTheory.AEStronglyMeasurable f μ | Path: Mathlib.MeasureTheory.Function.L1Space.Integrable",
      "informal_statement": "For any function $f \\colon \\alpha \\to \\beta$ that is integrable with respect to a measure $\\mu$, $f$ is almost everywhere strongly measurable."
    },
    {
      "full_name": "MeasureTheory.Integrable.mono'",
      "formal_statement": "Formal Name: MeasureTheory.Integrable.mono' | Kind: theorem | Type: ∀ {α : Type u_1} {β : Type u_2} {m : MeasurableSpace α} {μ : MeasureTheory.Measure α} [inst : NormedAddCommGroup β]\n  {f : α → β} {g : α → ℝ},\n  MeasureTheory.Integrable g μ →\n    MeasureTheory.AEStronglyMeasurable f μ → (∀ᵐ (a : α) ∂μ, ‖f a‖ ≤ g a) → MeasureTheory.Integrable f μ | Path: Mathlib.MeasureTheory.Function.L1Space.Integrable",
      "informal_statement": "Let $f \\colon \\alpha \\to \\beta$ and $g \\colon \\alpha \\to \\mathbb{R}$ be functions, where $\\alpha$ is a measure space and $\\beta$ is a normed additive commutative group. If $g$ is integrable with respect to a measure $\\mu$, $f$ is almost everywhere strongly measurable with respect to $\\mu$, and $\\|f(a)\\| \\leq g(a)$ holds almost everywhere with respect to $\\mu$, then $f$ is also integrable with respect to $\\mu$."
    },
    {
      "full_name": "MeasureTheory.Integrable.bdd_smul",
      "formal_statement": "Formal Name: MeasureTheory.Integrable.bdd_smul | Kind: theorem | Type: ∀ {α : Type u_1} {β : Type u_2} {m : MeasurableSpace α} {μ : MeasureTheory.Measure α} [inst : NormedAddCommGroup β]\n  {𝕜 : Type u_8} [inst_1 : NormedRing 𝕜] [inst_2 : Module 𝕜 β] [IsBoundedSMul 𝕜 β] {f : α → β} {φ : α → 𝕜},\n  MeasureTheory.Integrable f μ →\n    ∀ (C : ℝ), MeasureTheory.AEStronglyMeasurable φ μ → (∀ᵐ (a : α) ∂μ, ‖φ a‖ ≤ C) → MeasureTheory.Integrable (φ • f) μ | Path: Mathlib.MeasureTheory.Function.L1Space.Integrable",
      "informal_statement": "Let $(\\alpha,\\mathcal{A},\\mu)$ be a measure space, let $\\beta$ be a normed additive commutative group equipped with a bounded scalar multiplication by a normed ring $\\mathbb{K}$, and let $\\varphi:\\alpha\\to\\mathbb{K}$ be a function such that\\n\\n1. $\\varphi$ is $\\mu$‑almost everywhere strongly measurable, and\\n2. there exists a constant $C\\in\\mathbb{R}$ with $\\|\\varphi(x)\\|\\le C$ for $\\mu$‑almost all $x\\in\\alpha$.\\n\\nIf $f:\\alpha\\to\\beta$ is $\\mu$‑integrable, then the pointwise scalar multiple $x\\mapsto \\varphi(x)\\cdot f(x)$ is $\\mu$‑integrable."
    },
    {
      "full_name": "MeasureTheory.Integrable.aefinStronglyMeasurable",
      "formal_statement": "Formal Name: MeasureTheory.Integrable.aefinStronglyMeasurable | Kind: theorem | Type: ∀ {α : Type u_1} {G : Type u_2} {m0 : MeasurableSpace α} {μ : MeasureTheory.Measure α} [inst : NormedAddCommGroup G]\n  {f : α → G}, MeasureTheory.Integrable f μ → MeasureTheory.AEFinStronglyMeasurable f μ | Path: Mathlib.MeasureTheory.Function.StronglyMeasurable.Lp",
      "informal_statement": "If a function $f$ is integrable with respect to a measure $\\mu$, then $f$ is almost everywhere finitely strongly measurable, i.e., there exists a finitely strongly measurable function that is equal to $f$ $\\mu$-almost everywhere."
    }
  ]
}

